#!/usr/bin/env python3
"""Replay captured ring commands, native monster HP and the one-loop alternatives."""
import json
from pathlib import Path
import re
import sys

CASES={
 "left-ready":("Charged fire ring on the left", "A charged Ring of Flames is on the left hand; an ordinary Strength ring is on the right. The original ring-attack check overlooks the fire ring. The complete correction uses it."),
 "right-charging-left-ready":("Right fire ring recharging; left ready", "The right fire ring cannot be used yet, but the left one is ready. The correction uses the available left ring."),
 "right-control":("Control: fire ring on the right", "The right-hand fire ring works in every version. The other ring is an ordinary Strength ring."),
 "both-ready":("Control: both fire rings ready", "Every version keeps the existing preference for the right-hand ring."),
 "left-charging":("Control: left fire ring recharging", "The left ring is not ready to use. No version activates it."),
 "no-ring":("Control: no fire ring equipped", "Both rings are ordinary Strength rings. No fire-ring attack is available."),
 "blind-control":("Control: character is blind", "Blindness prevents this ring attack. Every version rejects it."),
}
PHASES=("before","detection-only","activation-only","after")

def generate(root):
 data={}
 for mode,(label,explanation) in CASES.items():
  item={"label":label,"explanation":explanation}
  for phase in PHASES:
   raw=(root/f"{phase}-{mode}.log").read_text();frames=[json.loads(l[6:]) for l in raw.splitlines() if l.startswith("FRAME ")]
   match=re.search(r"OUTCOME (.*)",raw)
   if len(frames)!=2 or not match:raise RuntimeError(f"Incomplete recording: {phase}/{mode}")
   outcome={k:int(v) for k,v in re.findall(r"(\w+)=(-?\d+)",match[1])}
   if frames[0]["enemy_hp"]-frames[1]["enemy_hp"]!=outcome["damage"]:raise RuntimeError("Native HP/outcome mismatch")
   item[phase]={"frames":frames,"outcome":outcome,"raw":raw}
  data[mode]=item
 payload=json.dumps(data).replace("<","\\u003c")
 (root/"replay.html").write_text(TEMPLATE.replace("__DATA__",payload));(root/"replay-data.json").write_text(json.dumps(data,indent=2)+"\n")
 print(f"Open in your browser: {root/'replay.html'}")

TEMPLATE=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>The overlooked left-hand ring</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f2ec;color:#233239;font:17px/1.6 system-ui,sans-serif}main{max-width:1080px;margin:auto;padding:34px 24px 60px}h1{font-size:clamp(30px,5vw,48px);line-height:1.15}h2{font-size:23px}.intro{font-size:20px}.card{background:white;border:1px solid #d1dad4;border-radius:12px;padding:23px;margin:20px 0}.panels{display:grid;grid-template-columns:1fr 1fr;gap:20px}.panels .card:first-child{border-top:6px solid #ad7a40}.panels .card:last-child{border-top:6px solid #347d70}.hp{font-size:40px;font-weight:750}.hp small{font-size:18px;font-weight:400}.bar{height:12px;background:#e7eeea;border-radius:6px;overflow:hidden}.fill{height:100%;background:#6d8b78}.action{padding:15px;background:#f0f4f1;border-radius:8px;min-height:100px}select,button{font:inherit;padding:10px 14px;border:1px solid #a8b8b2;border-radius:7px;background:white;max-width:100%}button{cursor:pointer}button.active{background:#245f59;color:white}.buttons{display:flex;gap:12px;flex-wrap:wrap;margin-top:20px}.summary{padding:18px 22px;background:#e4eeea;border-left:5px solid #34776b}table{width:100%;border-collapse:collapse;font-size:15px}th,td{padding:12px 8px;text-align:left;border-bottom:1px solid #cdd8d0}.limit{font-size:15px}details{margin:20px 0;background:white;padding:16px 20px;border-radius:8px}summary{cursor:pointer;font-weight:650}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:350px;overflow:auto;font:13px/1.5 ui-monospace,monospace}a{color:#24616a}@media(max-width:650px){.panels{grid-template-columns:1fr}main{padding:24px 16px}}</style><main>
<p>Recorded native ring attack · all four production-code versions compared</p><h1>A charged fire ring is overlooked on the left hand</h1><p class="intro">A Warrior has a charged Ring of Flames on the left hand and an ogre in range. The original ring-attack check requests no activation, leaving the ogre at70 HP. The complete correction activates the left ring and kills the ogre, removing its70 HP.</p><p>A Ring of Flames launches a fireball and gives temporary fire protection. The right-hand ring already works; the missing left-hand ring is the problem. This test isolates the ring attack, not the whole Borg's choice among all possible attacks.</p>
<section class="card"><label for="scenario"><strong>Choose a recorded situation</strong></label><br><select id="scenario"></select><p id="explanation"></p><label for="variant"><strong>Compare the original with:</strong></label><br><select id="variant"><option value="after">Both changes: find and activate either ring</option><option value="detection-only">Partial fix: only find either ring</option><option value="activation-only">Partial fix: only extend activation</option></select><div class="buttons"><button data-step="0">Start</button><button data-step="1" class="active">Show ring attack</button></div></section>
<div class="panels" aria-live="polite"><section id="original" class="card"><h2>Original Borg</h2><div class="hp"></div><div class="bar"><div class="fill"></div></div><p class="stats"></p><p class="action"></p></section><section id="compared" class="card"><h2 id="variant-title">Both changes</h2><div class="hp"></div><div class="bar"><div class="fill"></div></div><p class="stats"></p><p class="action"></p></section></div><p class="summary" id="outcome"></p>
<h2>Why both changes are needed</h2><table><thead><tr><th>Version</th><th>Cases passing</th><th>Left-hand attack</th></tr></thead><tbody><tr><td>Original</td><td>5/7</td><td>Ring not used</td></tr><tr><td>Only find either ring</td><td>5/7</td><td>Ring found, but still not activated</td></tr><tr><td>Only extend activation</td><td>5/7</td><td>Left ring still not found</td></tr><tr><td>Find and activate either ring</td><td>7/7</td><td>Ready left ring activates</td></tr></tbody></table>
<p>Each version uses the same actual native test, inventory, monster, seed and assertions. Only the production ring loops change. The five controls have identical logs in every version.</p><details><summary>What the experiment does and does not establish</summary><p>The test creates a Warrior, known rings and one visible ogre six squares away. It calls the real Borg fire-ring attack routine and validates its requested activation item and target. The native game executes that item activation, computes device success, applies the fireball, kills the monster and starts ring recharge/fire protection. No damage or success result is invented.</p><p>This is an isolated ring-attack check. It does not run the full Borg attack ranking, other available attacks, monster turns or a complete fight. The result demonstrates the missing left-ring attack and its execution after correction, not a player death or an overall survival benefit. The native device failure chance in this setup is49/1000; the shown seeded activation succeeds, not every possible attempt.</p><p>HP removed is capped at the ogre's remaining70 HP. This display does not claim that70 is the uncapped fireball damage.</p></details>
<details><summary>Recorded game output</summary><h3>Original</h3><pre id="original-log"></pre><h3>Compared version</h3><pre id="compared-log"></pre></details><p class="limit">Canonical report: <a href="https://github.com/diegoami/neo-angband-tracker/issues/78">issue78 / CBUG-0062</a>. Discovery credit: borg-rs.</p></main><script>
const data=__DATA__;const select=document.getElementById('scenario'),variant=document.getElementById('variant');let step=1;for(const [key,c] of Object.entries(data)){const o=document.createElement('option');o.value=key;o.textContent=c.label;select.append(o)}
function draw(){const c=data[select.value];document.getElementById('explanation').textContent=c.explanation;document.getElementById('variant-title').textContent=variant.options[variant.selectedIndex].text;for(const [panelName,phase] of [['original','before'],['compared',variant.value]]){const d=c[phase],f=d.frames[step],p=document.getElementById(panelName);p.querySelector('.hp').innerHTML=`${f.enemy_hp} <small>/ ${f.enemy_start_hp} ogre HP</small>`;p.querySelector('.fill').style.width=(100*f.enemy_hp/f.enemy_start_hp)+'%';p.querySelector('.stats').textContent=`Warrior HP: ${f.hp}. Right ring: ${f.right_timeout>0?'recharging':'ready'}. Left ring: ${f.left_timeout>0?'recharging':'ready'}. Temporary fire protection: ${f.fire_protection>0?'active':'absent'}.`;p.querySelector('.action').textContent=step===0?'Before the ring-attack check.':d.outcome.activated?`Activates the ${d.outcome.selected_slot===2?'right':'left'} ring. The ogre ${d.outcome.killed?'is killed':`has ${f.enemy_hp} HP left`}.`:'No ring activation is requested. The ogre keeps its HP.';document.getElementById(panelName+'-log').textContent=d.raw}const a=c.before.outcome,b=c[variant.value].outcome;document.getElementById('outcome').textContent=a.enemy_after!==b.enemy_after?`Recorded outcome: ogre HP ${a.enemy_after} → ${b.enemy_after}. The available left ring is now used.`:variant.value!=='after'&&['left-ready','right-charging-left-ready'].includes(select.value)?'This partial fix still leaves the ready left ring unused.':'Unchanged control: the same ring choice and outcome in both versions.';for(const b of document.querySelectorAll('[data-step]'))b.classList.toggle('active',Number(b.dataset.step)===step)}
select.addEventListener('change',()=>{step=1;draw()});variant.addEventListener('change',draw);for(const b of document.querySelectorAll('[data-step]'))b.addEventListener('click',()=>{step=Number(b.dataset.step);draw()});draw();</script></html>'''

if __name__=="__main__":generate(Path(sys.argv[1]).resolve())
